mapper.select:
SELECT EXISTS (
    SELECT 1 FROM event WHERE event_content_id = #{eventContentId}
)

mapper.insert:
INSERT INTO favorite_event (user_id, event_content_id)
SELECT #{userId}, #{eventContentId}
FROM event e
WHERE e.event_content_id = #{eventContentId}
  AND NOT EXISTS (
      SELECT 1 FROM favorite_event f
      WHERE f.user_id = #{userId}
        AND f.event_content_id = #{eventContentId}
  )

mapper.select:
SELECT COUNT(*)
FROM favorite_event
WHERE user_id = #{userId}

mapper.delete:
DELETE FROM favorite_event
WHERE event_content_id = #{eventContentId}
AND user_id = #{userId}
